// План specs/job-payments.md 2.1 (кейс .qa/tests/job-payments/JP-08). Pre-Prod, preprod-ttp + клиент без входа, десктоп Chrome, EN.
// #51cdcc: ссылка на оплату строится от адреса среды, в которой создана, и открывается (не «This payment link is not valid»).
// @writes @data: работа «QA-AUTO pay pay-page … #67b4b4» ($5) + ссылка $5.00. Оплаты нет; Text / Email не нажимаются.
// Очистка в finally: Cancel link, работа → Cancelled.
import { test, expect } from '../../fixtures';
import {
  PREPROD, REMAINING, blockMessaging, cancelJob, cancelOpenLinks, createJobWithBalance, createPaymentLink, escRe,
  expectPayPage, jobNumber, openCustomerContext, openPaymentsTab,
} from './payments-helpers';

test.describe('Job → Payments: Payment Link host (#51cdcc)', () => {
  test('QA-AUTO: Payment Link created in the environment starts with its address and /pay opens for the customer #51cdcc @desktop @writes @data', async ({ asUser, browser }, testInfo) => {
    test.setTimeout(180_000);
    const page = await asUser('preprod-ttp');
    const messaging = await blockMessaging(page);
    let jobUrl: string | null = null;
    const customer = await openCustomerContext(browser, testInfo);
    try {
      jobUrl = await createJobWithBalance(page, 'pay-page');
      await openPaymentsTab(page, jobUrl);
      const jobNo = await jobNumber(page);

      // Шаг 1: Create link — адрес текущей среды + /pay?t=, не app.techory.ai («מה רצוי»)
      const link = await createPaymentLink(page);
      expect(link).toMatch(new RegExp(`^${escRe(PREPROD)}/pay\\?t=`));
      expect(link, 'ссылка не на prod').not.toContain('app.techory.ai');

      // Шаг 2: клиент без входа открывает ссылку — страница оплаты, не «not valid» («מה רצוי»: נפתח ומאפשר תשלום)
      await customer.page.goto(link);
      await expect(customer.page).toHaveURL(new RegExp(`^${escRe(PREPROD)}/pay\\?t=`));
      await expectPayPage(customer.page, REMAINING, jobNo);

      expect(messaging, 'запросов отправки SMS/email быть не должно').toEqual([]);
    } finally {
      await customer.context.close();
      await cancelOpenLinks(page, jobUrl);
      await cancelJob(page, jobUrl);
    }
  });
});
